module sunlight_hours (input clk, input rst_n, input start, input [2:0] n_valid, input [15:0] x_data [0:7], input [15:0] h_data [0:7], output reg [15:0] sun_hours [0:7], output reg done); reg [15:0] x_reg [0:7]; reg [15:0] h_reg [0:7]; reg [2:0] n_reg; reg [31:0] max_slope_west; reg [31:0] max_slope_east; reg [31:0] sun_value; reg [3:0] state; reg [15:0] sun_hours_reg [0:7]; reg done_reg; reg [7:0] counter; localparam IDLE = 4'd0; localparam LOAD = 4'd1; localparam SWEEP_WEST = 4'd2; localparam SWEEP_EAST = 4'd3; localparam CALC = 4'd4; localparam DONE = 4'd5; always @(posedge clk) begin if (!rst_n) begin x_reg <= 0; h_reg <=0; n_reg <=0; max_slope_west <=0; max_slope_east <=0; sun_value <=0; state <= IDLE; done_reg <=0; sun_hours_reg <=0; counter <=0; end else begin if (state == IDLE) begin if (start) begin n_reg <= n_valid; x_reg <= x_data; h_reg <= h_data; state <= LOAD; end end else if (state == LOAD) begin state <= SWEEP_WEST; end else if (state == SWEEP_WEST) begin max_slope_west <=0; if (n_reg >1) begin int dx = x_reg[1] - x_reg[0]; int dh = h_reg[1] - h_reg[0]; if (dx >0 && dh >0) begin int slope = (dh <<16) / dx; if (slope > max_slope_west) max_slope_west <= slope; end end if (n_reg >2) begin int dx = x_reg[2] - x_reg[1]; int dh = h_reg[2] - h_reg[1]; if (dx >0 && dh >0) begin int slope = (dh <<16) / dx; if (slope > max_slope_west) max_slope_west <= slope; end end if (n_reg >3) begin int dx = x_reg[3] - x_reg[2]; int dh = h_reg[3] - h_reg[2]; if (dx >0 && dh >0) begin int slope = (dh <<16) / dx; if (slope > max_slope_west) max_slope_west <= slope; end end if (n_reg >4) begin int dx = x_reg[4] - x_reg[3]; int dh = h_reg[4] - h_reg[3]; if (dx >0 && dh >0) begin int slope = (dh <<16) / dx; if (slope > max_slope_west) max_slope_west <= slope; end end if (n_reg >5) begin int dx = x_reg[5] - x_reg[4]; int dh = h_reg[5] - h_reg[4]; if (dx >0 && dh >0) begin int slope = (dh <<16) / dx; if (slope > max_slope_west) max_slope_west <= slope; end end if (n_reg >6) begin int dx = x_reg[6] - x_reg[5]; int dh = h_reg[6] - h_reg[5]; if (dx >0 && dh >0) begin int slope = (dh <<16) / dx; if (slope > max_slope_west) max_slope_west <= slope; end end if (n_reg >7) begin int dx = x_reg[7] - x_reg[6]; int dh = h_reg[7] - h_reg[6]; if (dx >0 && dh >0) begin int slope = (dh <<16) / dx; if (slope > max_slope_west) max_slope_west <= slope; end end state <= SWEEP_EAST; end else if (state == SWEEP_EAST) begin max_slope_east <=0; if (n_reg >1) begin int dx = x_reg[1] - x_reg[0]; if (dx >0 && h_reg[1] > h_reg[0]) begin int slope = (h_reg[1]-h_reg[0]) <<16 / dx; if (slope > max_slope_east) max_slope_east <= slope; end end if (n_reg >2) begin int dx = x_reg[2] - x_reg[1]; if (dx >0 && h_reg[2]>h_reg[1]) begin int slope = (h_reg[2]-h_reg[1]) <<16 / dx; if (slope > max_slope_east) max_slope_east <= slope; end end if (n_reg >3) begin int dx = x_reg[3]-x_reg[2]; if (dx>0 && h_reg[3]>h_reg[2]) begin int slope = (h_reg[3]-h_reg[2]) <<16 / dx; if (slope > max_slope_east) max_slope_east <= slope; end end if (n_reg >4) begin int dx = x_reg[4]-x_reg[3]; if (dx>0 && h_reg[4]>h_reg[3]) begin int slope = (h_reg[4]-h_reg[3]) <<16 / dx; if (slope > max_slope_east) max_slope_east <= slope; end end if (n_reg >5) begin int dx = x_reg[5]-x_reg[4]; if (dx>0 && h_reg[5]>h_reg[4]) begin int slope = (h_reg[5]-h_reg[4]) <<16 / dx; if (slope > max_slope_east) max_slope_east <= slope; end end if (n_reg >6) begin int dx = x_reg[6]-x_reg[5]; if (dx>0 && h_reg[6]>h_reg[5]) begin int slope = (h_reg[6]-h_reg[5]) <<16 / dx; if (slope > max_slope_east) max_slope_east <= slope; end end if (n_reg >7) begin int dx = x_reg[7]-x_reg[6]; if (dx>0 && h_reg[7]>h_reg[6]) begin int slope = (h_reg[7]-h_reg[6]) <<16 / dx; if (slope > max_slope_east) max_slope_east <= slope; end end state <= CALC; end else if (state == CALC) begin sun_value = (18 <<16) - ((max_slope_west + max_slope_east) >>16); if (sun_value > (18<<16)) sun_value <= 18<<16; if (sun_value <0) sun_value <=0; sun_hours_reg <= 0; if (n_reg >=1) sun_hours_reg[0] <= sun_value >>16; if (n_reg >=2) sun_hours_reg[1] <= sun_value >>16; if (n_reg >=3) sun_hours_reg[2] <= sun_value >>16; if (n_reg >=4) sun_hours_reg[3] <= sun_value >>16; if (n_reg >=5) sun_hours_reg[4] <= sun_value >>16; if (n_reg >=6) sun_hours_reg[5] <= sun_value >>16; if (n_reg >=7) sun_hours_reg[6] <= sun_value >>16; if (n_reg >=8) sun_hours_reg[7] <= sun_value >>16; state <= DONE; done_reg <=1; end else if (state == DONE) begin if (start) begin state <= IDLE; done_reg <=0; end end end end end assign sun_hours = sun_hours_reg; assign done = done_reg; endmodule